sed -i '' 's/import { dashboardSummary, entitiesData, riskDistribution, findingsByCategory, findingsTrend } from '"'"'@\/data'"'"';/import { DashboardService, EntityService } from '"'"'@\/services\/api'"'"';\nimport { useState, useEffect } from '"'"'react'"'"';/g' src/pages/Dashboard/index.tsx

sed -i '' 's/export const Dashboard = () => {/export const Dashboard = () => {\n  const [data, setData] = useState<any>(null);\n  const [entities, setEntities] = useState<any[]>([]);\n\n  useEffect(() => {\n    const fetchData = async () => {\n      const [dashData, entitiesData] = await Promise.all([\n        DashboardService.getDashboardData(),\n        EntityService.getEntities()\n      ]);\n      setData(dashData);\n      setEntities(entitiesData);\n    };\n    fetchData();\n  }, []);\n\n  if (!data) return <div className="p-8 text-center text-gray-500">Loading dashboard...<\/div>;\n\n  const { summary: dashboardSummary, riskDistribution, findingsByCategory, findingsTrend } = data;\n  const entitiesData = entities;\n/g' src/pages/Dashboard/index.tsx
